class V1PresentationDependencies(val getStore:GetStore,val connectStore:ConnectStore,val disconnectStore:DisconnectStore,val getOrders:GetOrders,val getSalesSummary:GetSalesSummary,val getOrder:GetOrder,val updateOrder:UpdateOrder,val addOrderNote:AddOrderNote,val getProducts:GetProducts,val getProduct:GetProduct,val createProduct:CreateProduct,val updateProduct:UpdateProduct,val deleteProduct:DeleteProduct,val getProductCategories:GetProductCategories,val getMedia:GetMedia,val getVariations:GetVariations,val getVariation:GetVariation,val createVariation:CreateVariation,val updateVariation:UpdateVariation,val deleteVariation:DeleteVariation,val getAttributes:GetAttributes,val getAttribute:GetAttribute,val createAttribute:CreateAttribute,val updateAttribute:UpdateAttribute,val deleteAttribute:DeleteAttribute,val getTerms:GetTerms,val getTerm:GetTerm,val createTerm:CreateTerm,val updateTerm:UpdateTerm,val deleteTerm:DeleteTerm,val uploadMedia:UploadMedia,val deleteMedia:DeleteMedia,val getConnectionState:GetConnectionState,val getSyncState:GetSyncState,val getPending:GetPendingOperations,val getConflicts:suspend(StoreId)->CoreResult<List<Conflict>>,val resolveConflict:suspend(StoreId,EntityId,ConflictResolution)->CoreResult<Unit>,val syncPending:SyncPendingOperations,val initialStoreId:String?,val onStoreConnected:(String)->Unit,val onStoreDisconnected:()->Unit)
sealed interface FeatureUiState<out T>{data object Loading:FeatureUiState<Nothing>;data object Empty:FeatureUiState<Nothing>;data class Success<T>(val value:T):FeatureUiState<T>;data class Error(val message:String,val retryable:Boolean=true):FeatureUiState<Nothing>;data object Offline:FeatureUiState<Nothing>;data object Pending:FeatureUiState<Nothing>;data class Conflict(val count:Int=1):FeatureUiState<Nothing>}
private fun CoreResult.Failure.toUi()=FeatureUiState.Error(PresentationErrorMapper.message(error),error.recoverable)
class ConnectionViewModel(private val d:V1PresentationDependencies):ViewModel(){private val _state=MutableStateFlow<FeatureUiState<StoreConnection>>(FeatureUiState.Empty);val state:StateFlow<FeatureUiState<StoreConnection>> = _state.asStateFlow();fun connect(url:String,key:String,secret:String)=viewModelScope.launch{_state.value=FeatureUiState.Loading;val u=url.trim().trimEnd('/');if(!u.startsWith("https://")&&!u.startsWith("http://")){_state.value=FeatureUiState.Error("آدرس فروشگاه باید با HTTP یا HTTPS شروع شود.",false)}else{try{when(val r=d.connectStore(StoreConnection(StoreId("store-${u.lowercase().hashCode().toUInt().toString(16)}"),u,ConnectionState.DISCONNECTED,null),key,secret)){is CoreResult.Success->_state.value=FeatureUiState.Success(r.value);is CoreResult.Failure->_state.value=r.toUi()}}catch(_:Throwable){_state.value=FeatureUiState.Offline}}}}
private object OrdersMemoryCache { val data = linkedMapOf<String, MutableList<Order>>() }
class OrdersViewModel(private val d:V1PresentationDependencies):ViewModel(){private val _state=MutableStateFlow<FeatureUiState<List<Order>>>(FeatureUiState.Loading);val state:StateFlow<FeatureUiState<List<Order>>> = _state.asStateFlow();private var page=1;private var query="";private var job:Job?=null;private var loadingMore=false;private var hasMore=true;fun hasMore():Boolean=hasMore;fun load(s:StoreId,search:String="",reset:Boolean=true){val normalized=search.trim();query=normalized;if(reset){page=1;hasMore=true;loadingMore=false};job?.cancel();job=viewModelScope.launch{if(reset&&normalized.isBlank())OrdersMemoryCache.data[s.value]?.takeIf{it.isNotEmpty()}?.let{_state.value=FeatureUiState.Success(it.toList())};delay(if(normalized.isBlank())0 else 300);try{when(val r=d.getOrders(s,1,30,normalized.ifBlank{null},null)){is CoreResult.Success->{page=1;hasMore=r.value.size>=30;if(normalized.isBlank())OrdersMemoryCache.data[s.value]=r.value.toMutableList();_state.value=if(r.value.isEmpty())FeatureUiState.Empty else FeatureUiState.Success(r.value)};is CoreResult.Failure->{if(OrdersMemoryCache.data[s.value].isNullOrEmpty()||normalized.isNotBlank())_state.value=r.toUi()}}}catch(_:Throwable){if(OrdersMemoryCache.data[s.value].isNullOrEmpty()||normalized.isNotBlank())_state.value=FeatureUiState.Error("بارگذاری سفارش‌ها ناموفق بود. اتصال فروشگاه را بررسی کنید.",true)}}};fun nextPage(s:StoreId)=viewModelScope.launch{if(!loadingMore&&hasMore){loadingMore=true;try{val target=page+1;when(val r=d.getOrders(s,target,30,query.ifBlank{null},null)){is CoreResult.Success->{page=target;hasMore=r.value.size>=30;val old=(_state.value as? FeatureUiState.Success)?.value.orEmpty();val merged=(old+r.value).distinctBy{it.id};if(query.isBlank())OrdersMemoryCache.data[s.value]=merged.toMutableList();_state.value=FeatureUiState.Success(merged)};is CoreResult.Failure->_state.value=r.toUi()}}catch(_:Throwable){_state.value=FeatureUiState.Error("بارگذاری سفارش‌های بیشتر ناموفق بود.",true)}finally{loadingMore=false}}}}
class OrderDetailViewModel(private val d:V1PresentationDependencies):ViewModel(){private val _state=MutableStateFlow<FeatureUiState<Order>>(FeatureUiState.Loading);val state=_state.asStateFlow();fun load(s:StoreId,id:EntityId)=viewModelScope.launch{try{when(val r=d.getOrder(s,id)){is CoreResult.Success->_state.value=FeatureUiState.Success(r.value);is CoreResult.Failure->_state.value=r.toUi()}}catch(_:Throwable){_state.value=FeatureUiState.Offline}};fun update(s:StoreId,o:Order)=viewModelScope.launch{_state.value=FeatureUiState.Pending;try{when(val r=d.updateOrder(s,o.id,o)){is CoreResult.Success->_state.value=FeatureUiState.Success(r.value);is CoreResult.Failure->_state.value=r.toUi()}}catch(_:Throwable){_state.value=FeatureUiState.Offline}};fun updateStatus(s:StoreId,status:OrderStatus)=viewModelScope.launch{val current=(_state.value as? FeatureUiState.Success)?.value;if(current!=null)update(s,current.copy(status=status))};fun note(s:StoreId,id:EntityId,text:String)=viewModelScope.launch{try{when(d.addOrderNote(s,id,text)){is CoreResult.Success->Unit;is CoreResult.Failure->_state.value=FeatureUiState.Error("افزودن یادداشت ناموفق بود.")}}catch(_:Throwable){_state.value=FeatureUiState.Offline}}}
class ProductsViewModel(private val d:V1PresentationDependencies):ViewModel(){private val _state=MutableStateFlow<FeatureUiState<List<Product>>>(FeatureUiState.Loading);val state:StateFlow<FeatureUiState<List<Product>>> = _state.asStateFlow();var page=1;private var query="";private var job:Job?=null;private var loadingMore=false;private var hasMore=true;fun load(s:StoreId,search:String="",reset:Boolean=true){query=search.trim();if(reset){page=1;hasMore=true;loadingMore=false};job?.cancel();job=viewModelScope.launch{if(query.isNotBlank())delay(300);try{when(val r=d.getProducts(s,page,30,query.ifBlank{null})){is CoreResult.Success->{val unique=r.value.distinctBy{it.id};hasMore=unique.size>=30;_state.value=if(unique.isEmpty()&&page==1)FeatureUiState.Empty else FeatureUiState.Success(unique)};is CoreResult.Failure->{if(_state.value !is FeatureUiState.Success)_state.value=r.toUi()}}}catch(_:Throwable){if(_state.value !is FeatureUiState.Success)_state.value=FeatureUiState.Offline}}};fun nextPage(s:StoreId)=viewModelScope.launch{if(!loadingMore&&hasMore){loadingMore=true;try{val target=page+1;when(val r=d.getProducts(s,target,30,query.ifBlank{null})){is CoreResult.Success->{page=target;hasMore=r.value.size>=30;val old=(_state.value as? FeatureUiState.Success)?.value.orEmpty();_state.value=FeatureUiState.Success((old+r.value).distinctBy{it.id})};is CoreResult.Failure->_state.value=r.toUi()}}catch(_:Throwable){_state.value=FeatureUiState.Error("بارگذاری محصولات بیشتر ناموفق بود.",true)}finally{loadingMore=false}}}}
class ProductDetailViewModel(private val d:V1PresentationDependencies):ViewModel(){private val _state=MutableStateFlow<FeatureUiState<Product>>(FeatureUiState.Loading);val state=_state.asStateFlow();private val _categories=MutableStateFlow<FeatureUiState<List<IdName>>>(FeatureUiState.Loading);val categories:StateFlow<FeatureUiState<List<IdName>>> = _categories.asStateFlow();fun load(s:StoreId,id:EntityId)=viewModelScope.launch{_state.value=FeatureUiState.Loading;try{when(val r=d.getProduct(s,id)){is CoreResult.Success->_state.value=FeatureUiState.Success(r.value);is CoreResult.Failure->_state.value=r.toUi()}}catch(_:Throwable){_state.value=FeatureUiState.Offline};loadCategories(s)};fun loadCategories(s:StoreId)=viewModelScope.launch{_categories.value=FeatureUiState.Loading;try{when(val r=d.getProductCategories(s,1,100,null)){is CoreResult.Success->_categories.value=FeatureUiState.Success(r.value);is CoreResult.Failure->_categories.value=r.toUi()}}catch(_:Throwable){_categories.value=FeatureUiState.Offline}};fun save(s:StoreId,p:Product,create:Boolean,done:()->Unit)=viewModelScope.launch{_state.value=FeatureUiState.Pending;try{when(val r=if(create)d.createProduct(s,p)else d.updateProduct(s,p.id,p)){is CoreResult.Success->{_state.value=FeatureUiState.Success(r.value);done()};is CoreResult.Failure->_state.value=r.toUi()}}catch(_:Throwable){_state.value=FeatureUiState.Offline}};fun delete(s:StoreId,id:EntityId,done:()->Unit)=viewModelScope.launch{_state.value=FeatureUiState.Pending;try{when(val r=d.deleteProduct(s,id)){is CoreResult.Success->{_state.value=FeatureUiState.Empty;done()};is CoreResult.Failure->_state.value=r.toUi()}}catch(_:Throwable){_state.value=FeatureUiState.Offline}}}
class SiteMediaViewModel(private val d:V1PresentationDependencies):ViewModel(){private val _state=MutableStateFlow<FeatureUiState<List<ProductImage>>>(FeatureUiState.Loading);val state:StateFlow<FeatureUiState<List<ProductImage>>> = _state.asStateFlow();var page=1;private var query="";private var loadingMore=false;private var hasMore=true;fun load(s:StoreId,search:String="",reset:Boolean=true)=viewModelScope.launch{query=search;if(reset){page=1;hasMore=true;loadingMore=false;_state.value=FeatureUiState.Loading};try{when(val r=d.getMedia(s,page,30,query.ifBlank{null})){is CoreResult.Success->{hasMore=r.value.size>=30;_state.value=if(r.value.isEmpty()&&page==1)FeatureUiState.Empty else FeatureUiState.Success(r.value)};is CoreResult.Failure->_state.value=r.toUi()}}catch(_:Throwable){_state.value=FeatureUiState.Offline}};fun nextPage(s:StoreId)=viewModelScope.launch{if(!loadingMore&&hasMore){loadingMore=true;try{val target=page+1;when(val r=d.getMedia(s,target,30,query.ifBlank{null})){is CoreResult.Success->{page=target;hasMore=r.value.size>=30;val old=(_state.value as? FeatureUiState.Success)?.value.orEmpty();_state.value=FeatureUiState.Success(old+r.value)};is CoreResult.Failure->_state.value=r.toUi()}}catch(_:Throwable){_state.value=FeatureUiState.Error("بارگذاری رسانه بیشتر ناموفق بود.",true)}finally{loadingMore=false}}}}
class VariationsViewModel(private val d:V1PresentationDependencies):ViewModel(){private val _state=MutableStateFlow<FeatureUiState<List<Variation>>>(FeatureUiState.Loading);val state=_state.asStateFlow();fun load(s:StoreId,p:EntityId,page:Int=1)=viewModelScope.launch{try{when(val r=d.getVariations(s,p,page,30)){is CoreResult.Success->_state.value=if(r.value.isEmpty())FeatureUiState.Empty else FeatureUiState.Success(r.value);is CoreResult.Failure->_state.value=r.toUi()}}catch(_:Throwable){_state.value=FeatureUiState.Offline}}}
class VariationEditorViewModel(private val d:V1PresentationDependencies):ViewModel(){private val _state=MutableStateFlow<FeatureUiState<Variation>>(FeatureUiState.Loading);val state=_state.asStateFlow();fun load(s:StoreId,p:EntityId,id:EntityId)=viewModelScope.launch{try{when(val r=d.getVariation(s,p,id)){is CoreResult.Success->_state.value=FeatureUiState.Success(r.value);is CoreResult.Failure->_state.value=r.toUi()}}catch(_:Throwable){_state.value=FeatureUiState.Offline}};fun save(s:StoreId,p:EntityId,id:EntityId,v:Variation,create:Boolean,done:()->Unit)=viewModelScope.launch{_state.value=FeatureUiState.Pending;try{when(val r=if(create)d.createVariation(s,v)else d.updateVariation(s,p,id,v)){is CoreResult.Success->{_state.value=FeatureUiState.Success(r.value);done()};is CoreResult.Failure->_state.value=r.toUi()}}catch(_:Throwable){_state.value=FeatureUiState.Offline}}}
class AttributesViewModel(private val d:V1PresentationDependencies):ViewModel(){private val _state=MutableStateFlow<FeatureUiState<List<GlobalAttribute>>>(FeatureUiState.Loading);val state:StateFlow<FeatureUiState<List<GlobalAttribute>>> = _state.asStateFlow();fun load(s:StoreId)=viewModelScope.launch{try{when(val r=d.getAttributes(s,1,100)){is CoreResult.Success->_state.value=if(r.value.isEmpty())FeatureUiState.Empty else FeatureUiState.Success(r.value);is CoreResult.Failure->_state.value=r.toUi()}}catch(_:Throwable){_state.value=FeatureUiState.Offline}};fun add(s:StoreId,v:GlobalAttribute)=viewModelScope.launch{try{when(val r=d.createAttribute(s,v)){is CoreResult.Success->load(s);is CoreResult.Failure->_state.value=r.toUi()}}catch(_:Throwable){_state.value=FeatureUiState.Offline}}}
class TermsViewModel(private val d:V1PresentationDependencies):ViewModel(){private val _state=MutableStateFlow<FeatureUiState<List<AttributeTerm>>>(FeatureUiState.Loading);val state:StateFlow<FeatureUiState<List<AttributeTerm>>> = _state.asStateFlow();fun load(s:StoreId,a:EntityId)=viewModelScope.launch{try{when(val r=d.getTerms(s,a,1,100)){is CoreResult.Success->_state.value=if(r.value.isEmpty())FeatureUiState.Empty else FeatureUiState.Success(r.value);is CoreResult.Failure->_state.value=r.toUi()}}catch(_:Throwable){_state.value=FeatureUiState.Offline}};fun add(s:StoreId,a:EntityId,v:AttributeTerm)=viewModelScope.launch{try{when(val r=d.createTerm(s,a,v)){is CoreResult.Success->load(s,a);is CoreResult.Failure->_state.value=r.toUi()}}catch(_:Throwable){_state.value=FeatureUiState.Offline}}}
class SyncViewModel(private val d:V1PresentationDependencies):ViewModel(){private val _state=MutableStateFlow<FeatureUiState<SyncMetadata>>(FeatureUiState.Loading);val state:StateFlow<FeatureUiState<SyncMetadata>> = _state.asStateFlow();fun load(s:StoreId)=viewModelScope.launch{try{when(val r=d.getSyncState(s)){is CoreResult.Success->_state.value=FeatureUiState.Success(r.value);is CoreResult.Failure->_state.value=r.toUi()}}catch(_:Throwable){_state.value=FeatureUiState.Offline}};fun sync(s:StoreId)=viewModelScope.launch{_state.value=FeatureUiState.Pending;try{when(d.syncPending(s)){is CoreResult.Success->load(s);is CoreResult.Failure->_state.value=FeatureUiState.Error("همگام‌سازی ناموفق بود.")}}catch(_:Throwable){_state.value=FeatureUiState.Offline}}}
class ConflictsViewModel(private val d:V1PresentationDependencies):ViewModel(){private val _state=MutableStateFlow<FeatureUiState<List<Conflict>>>(FeatureUiState.Loading);val state:StateFlow<FeatureUiState<List<Conflict>>> = _state.asStateFlow();fun load(s:StoreId)=viewModelScope.launch{try{when(val r=d.getConflicts(s)){is CoreResult.Success->_state.value=if(r.value.isEmpty())FeatureUiState.Empty else FeatureUiState.Success(r.value);is CoreResult.Failure->_state.value=r.toUi()}}catch(_:Throwable){_state.value=FeatureUiState.Offline}};fun resolve(s:StoreId,id:EntityId,r:ConflictResolution)=viewModelScope.launch{try{when(d.resolveConflict(s,id,r)){is CoreResult.Success->load(s);is CoreResult.Failure->_state.value=FeatureUiState.Error("حل تعارض ناموفق بود.")}}catch(_:Throwable){_state.value=FeatureUiState.Offline}}}
